CREATE OR REPLACE FUNCTION public.orders_set_financial_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  proj_country public.country;
BEGIN
  -- keep updated_at fresh
  NEW.updated_at := now();

  ----------------------------------------------------------------
  -- Get country of the project through projects -> emails
  ----------------------------------------------------------------
  SELECT e.country
  INTO proj_country
  FROM public.projects p
  JOIN public.emails   e ON e.email_id = p.email_id
  WHERE p.project_id = NEW.project_id
  LIMIT 1;

  ----------------------------------------------------------------
  -- net_sum = quantity * unit_price
  ----------------------------------------------------------------
  IF NEW.quantity IS NULL OR NEW.unit_price IS NULL THEN
    NEW.net_sum := NULL;
  ELSE
    NEW.net_sum := (NEW.quantity::numeric * NEW.unit_price);
  END IF;

  ----------------------------------------------------------------
  -- db_1 = net_sum - cost
  ----------------------------------------------------------------
  IF NEW.net_sum IS NULL OR NEW.cost IS NULL THEN
    NEW.db_1 := NULL;
  ELSE
    NEW.db_1 := (NEW.net_sum - NEW.cost);
  END IF;

  ----------------------------------------------------------------
  -- ROI: db_1 / cost
  -- make it NULL on divide-by-zero
  ----------------------------------------------------------------
  IF NEW.db_1 IS NULL OR NEW.cost IS NULL THEN
    NEW.roi := NULL;
  ELSIF NEW.cost = 0 THEN
    NEW.roi := NULL;  -- divide by zero -> NULL
  ELSE
    NEW.roi := (NEW.db_1 / NEW.cost);
  END IF;

  ----------------------------------------------------------------
  -- profit_margin = db_1 / net_sum
  -- make it NULL on divide-by-zero
  ----------------------------------------------------------------
  IF NEW.db_1 IS NULL OR NEW.net_sum IS NULL THEN
    NEW.profit_margin := NULL;
  ELSIF NEW.net_sum = 0 THEN
    NEW.profit_margin := NULL;  -- <-- changed from 0 to NULL
  ELSE
    NEW.profit_margin := (NEW.db_1 / NEW.net_sum);
  END IF;

  ----------------------------------------------------------------
  -- gross_sum logic (country-based VAT)
  ----------------------------------------------------------------
  IF NEW.net_sum IS NULL THEN
    NEW.gross_sum := NULL;
  ELSE
    IF proj_country = 'Germany' THEN
      NEW.gross_sum := NEW.net_sum * 1.19;
    ELSIF proj_country IN ('Austria', 'USA', 'Switzerland') THEN
      NEW.gross_sum := NEW.net_sum;
    ELSE
      NEW.gross_sum := NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.orders_set_product_from_name()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Copy product_name into product column
  NEW.product := NEW.product_name;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_orders_update_company_revenue()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    v_old_company_id bigint;
    v_new_company_id bigint;
begin
    -- figure out old company (for UPDATE/DELETE)
    if (tg_op = 'UPDATE' or tg_op = 'DELETE') then
        select e.company_id
        into v_old_company_id
        from public.orders   o
        join public.projects p on p.project_id = old.project_id
        join public.emails   e on e.email_id   = p.email_id;
    end if;

    -- figure out new company (for INSERT/UPDATE)
    if (tg_op = 'INSERT' or tg_op = 'UPDATE') then
        select e.company_id
        into v_new_company_id
        from public.orders   o
        join public.projects p on p.project_id = new.project_id
        join public.emails   e on e.email_id   = p.email_id;
    end if;

    -- refresh affected companies
    if v_old_company_id is not null then
        perform public.refresh_company_sum_of_revenue(v_old_company_id);
    end if;

    if v_new_company_id is not null
       and (v_new_company_id is distinct from v_old_company_id) then
        perform public.refresh_company_sum_of_revenue(v_new_company_id);
    end if;

    -- return proper row
    if tg_op = 'DELETE' then
        return old;
    else
        return new;
    end if;
end;
$function$
